import { useState } from "react";

const Sort = (props) => {
    const keys = Object.keys(props.fullData[0]);
    const allOptions = getOptionsArray(keys);

    const getDefaultSort = () => [
        { desc: false, label: 'Первый уровень', selected: 0, options: allOptions },
        { desc: false, label: 'Второй уровень', selected: 0, options: allOptions },
        { desc: false, label: 'Третий уровень', selected: 0, options: allOptions }
    ];

    const [levels, setLevels] = useState(getDefaultSort);

    const handleSubmit = (event) => {
        event.preventDefault();
        const sortArr = createSortArr(levels, keys);

        if (sortArr.length === 0) {
            return;
        }

        let sortedData = [...props.data].sort((first, second) => {
            for (let { key, direction } of sortArr) {
                let firstValue = first[key];
                let secondValue = second[key];
                let comparison = 0;

                if (["Вес", "Размер", "Продолжительность жизни", "Год открытия"].includes(key)) {
                    comparison = Number(firstValue) - Number(secondValue);
                } else {
                    comparison = String(firstValue).localeCompare(String(secondValue));
                }

                if (comparison !== 0) {
                    return direction ? -comparison : comparison;
                }
            }

            return 0;
        });

        props.sorting(sortedData);
    }

    const handleReset = () => {
        setLevels(getDefaultSort());
        props.sorting(props.fullData);
    }

    const handleChange = (levelIndex, value) => {
        setLevels((allLevels) =>
            allLevels.map((level, index) => {
                if (index === levelIndex) {
                    return { ...level, selected: parseInt(value) }
                }

                if (parseInt(value) === 0 && index > levelIndex) {
                    return { ...level, selected: 0, desc: false }
                }

                return level;
            })
        );
    }

    const handleCheck = (levelIndex, value) => {
        setLevels((allLevels) =>
            allLevels.map((level, index) =>
                index === levelIndex ? { ...level, desc: value } : level
            )
        );
    }

    const sortLevels = levels.map((level, index) => {
        const isDisabled = index > 0 && levels[index - 1].selected === 0;

        return (
            <p key={ index }>
                <label>{level.label}: </label>
                <select
                    value={ level.selected }
                    disabled={ isDisabled }
                    onChange={ (e) => handleChange(index, e.target.value) }
                >
                    {level.options.map((option) =>
                        <option key={ option.value } value={ option.value }>{option.label}</option>
                    )}
                </select>
                <label> по убыванию? </label>
                <input
                    type="checkbox"
                    checked={ level.desc }
                    onChange={ (e) => handleCheck(index, e.target.checked) }
                />
            </p>
        )
    });

    return (
        <form onSubmit={ handleSubmit } onReset={ handleReset }>
            {sortLevels}
            <button type="submit">Сортировать</button>
            <button type="reset">Сбросить сортировку</button>
        </form>
    );
}

const getType = (keys) => {
    let i = 0;
    const types = [{},{}];
    keys.forEach((key) => {
        if (i < 4) types
    })
}

const getOptionsArray = (options) => {
    let arr = [{ value: 0, label: "Нет" }];

    options.forEach((item, index) => {
        arr.push({ value: index + 1, label: item });
    });

    return arr;
}

const createSortArr = (levels, keys) => {
    let sortArr = [];

    for (const level of levels) {
        if (level.selected === 0) {
            break;
        }

        sortArr.push({
            key: keys[level.selected - 1],
            direction: level.desc
        });
    }

    return sortArr;
}

export default Sort;
